    "tables": {
      "l": "data/listings.csv"
    },
    "code": "l[l['year'].isin([2011, 2012])].assign(period='2011-2012', any_undressed=lambda d: d['Man partially unclothed'] | d['Woman partially unclothed']).groupby('period')[['Man partially unclothed', 'Woman partially unclothed', 'any_undressed']].sum()"
  },
  {
    "id": "raunchiness-over-quarter-mid-2010s",
    "source": "While the overall rate for covers featuring some state of undress remained over a quarter of titles, the rate for unclothed women peaked in 2015 at 11%.",
