    "tables": {
      "l": "data/listings.csv"
    },
    "code": "l[(l['year'] >= 2013) & (l['year'] <= 2015)].assign(undressed=l['Man partially unclothed'] | l['Woman partially unclothed']).groupby('year')['undressed'].mean().mul(100).round(1)"
  },
  {
    "id": "unclothed-women-peak-2015",
    "source": "the rate for unclothed women peaked in 2015 at 11%",
    "claim": "The share of covers with a partially unclothed woman was highest in 2015, at 10.9%.",
    "tables": {
      "l": "data/listings.csv"
    },
    "code": "l.groupby('year')['Woman partially unclothed'].mean().mul(100).round(1)"
